var i=`mutation-testing`;var s=87;var n={en:[{id:`T087-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Mutation Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Static analysis inspects source or compiled representations without executing full application behavior.`},{id:`B`,text:`Mutation testing changes code in small controlled ways and checks whether the test suite detects those changes.`},{id:`C`,text:`The testing pyramid recommends many fast, focused tests and fewer expensive full-system tests.`},{id:`D`,text:`Contract testing verifies assumptions between service providers and consumers, such as request shapes, response semantics and event schemas.`}]},{id:`T087-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Mutation Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Look for duplicated policy, long methods, feature envy, tangled dependencies and unclear names; identify the underlying change pressure.`},{id:`B`,text:`Record debt with business impact, risk, affected modules, approximate remediation cost and triggers.`},{id:`C`,text:`Typical mutants reverse comparisons, remove conditions or alter return values.`},{id:`D`,text:`Describe meaningful scenarios in Given-When-Then form, including counterexamples and business vocabulary.`}]},{id:`T087-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which practical project example best illustrates `},{t:`Mutation Testing`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`An MVP may hardcode one shipping provider to ship quickly, while noting the migration work. When a second provider becomes real, extract the adapter before duplicate integrations spread.`},{id:`B`,text:`A booking service has unit tests for cancellation windows, integration tests for double-booking prevention and a Playwright scenario for staff confirmation.`},{id:`C`,text:`A 300-line booking controller may contain validation, pricing and persistence. Extract coherent policies and retain a thin orchestrator, confirming the same responses and side effects.`},{id:`D`,text:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`}]},{id:`T087-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Mutation Testing`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Shorter methods are not always clearer, and refactoring mixed with new features is hard to review.`},{id:`B`,text:`A large number of mocked unit tests may miss broken integration behavior.`},{id:`C`,text:`Mutation tooling can be slow and noisy; equivalent mutants cannot be distinguished automatically in general.`},{id:`D`,text:`Not every imperfect design is debt worth repaying.`}]},{id:`T087-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It measures test sensitivity rather than raw test count or code coverage.`}]}]},{id:`T087-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A high mutation score guarantees the program meets the product requirements.`}]}]},{id:`T087-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`High mutation score is not proof of correct requirements or secure architecture.`}]}]},{id:`T087-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Mutation Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Typical mutants reverse comparisons, remove conditions or alter return values.`},{id:`B`,text:`Mutation testing changes code in small controlled ways and checks whether the test suite detects those changes.`},{id:`C`,text:`Static analysis can prove every runtime business rule is implemented correctly.`},{id:`D`,text:`Mutations that survive tests always indicate a production bug.`}]},{id:`T087-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Mutation Testing`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`High mutation score is not proof of correct requirements or secure architecture.`},{id:`B`,text:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`},{id:`C`,text:`BDD scenarios are useful only to QA engineers and not to product stakeholders.`},{id:`D`,text:`A high mutation score guarantees the program meets the product requirements.`}]},{id:`T087-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to identify three concrete code smells and propose a series of small diffs, each with preserved behavior and regression tests.`},{id:`B`,text:`Ask an agent to build a testing plan for a checkout workflow, map each requirement to the cheapest effective test layer and quantify expected runtime.`},{id:`C`,text:`Ask an agent to rank five debt items by risk, frequency and refactoring cost, then propose incremental repayment with test and rollback checkpoints.`},{id:`D`,text:`Ask an agent to run mutation testing on a pricing policy, inspect surviving boundary mutants and add targeted tests instead of blanket coverage increases.`}]},{id:`T087-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`What does a surviving mutant reveal that statement coverage cannot?`}]}]},{id:`T087-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Mutation Testing`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T087-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`,b:!0},{t:` — propose three checks for `},{t:`Mutation Testing`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T087-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T087-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Mutation Testing`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`If changing a discount eligibility check from less-than to less-than-or-equal leaves all tests green, the threshold boundary is insufficiently tested.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T087-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Мутаційне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Статичний аналіз перевіряє код або проміжне представлення без повного виконання застосунку.`},{id:`B`,text:`Мутаційне тестування вносить невеликі контрольовані зміни до коду й перевіряє, чи виявляють їх тести.`},{id:`C`,text:`Піраміда тестування радить мати багато швидких точкових тестів і менше дорогих наскрізних.`},{id:`D`,text:`Контрактне тестування перевіряє домовленості між провайдером і споживачем: форми запитів, семантику відповідей і схеми подій.`}]},{id:`T087-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Мутаційне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Шукайте дублювання правил, довгі методи, feature envy, заплутані залежності й нечіткі назви; визначайте справжню причину проблеми.`},{id:`B`,text:`Фіксуйте борг із бізнесовим впливом, ризиком, модулями, приблизною ціною виправлення й тригерами.`},{id:`C`,text:`Типові мутанти змінюють знак порівняння, прибирають умову або змінюють повернення.`},{id:`D`,text:`Описуйте сценарії через Given-When-Then із контрприкладами та бізнес-лексикою.`}]},{id:`T087-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який приклад із практичного проєкту найкраще ілюструє `},{t:`Мутаційне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`MVP може тимчасово зафіксувати одного провайдера доставки, задокументувавши майбутню міграцію. Коли з’явиться другий, виділіть адаптер до поширення дублікатів.`},{id:`B`,text:`Сервіс бронювання має unit-тести періоду скасування, інтеграційні тести захисту від подвійного бронювання та Playwright-сценарій підтвердження співробітником.`},{id:`C`,text:`Контролер бронювань на 300 рядків може містити валідацію, ціну й збереження. Винесіть узгоджені правила та залиште тонкий оркестратор, перевіривши незмінність відповідей і побічних ефектів.`},{id:`D`,text:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`}]},{id:`T087-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Мутаційне тестування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Коротші методи не завжди ясніші, а рефакторинг разом із новими фічами важко перевіряти.`},{id:`B`,text:`Велика кількість unit-тестів із mocks може пропустити поламані інтеграції.`},{id:`C`,text:`Мутаційні інструменти можуть бути повільними й шумними; еквівалентні мутанти не завжди можливо автоматично відрізнити.`},{id:`D`,text:`Не кожен недосконалий дизайн варто виправляти.`}]},{id:`T087-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Воно оцінює чутливість тестів, а не їхню кількість або покриття рядків.`}]}]},{id:`T087-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Високий mutation score гарантує відповідність продукту бізнес-вимогам.`}]}]},{id:`T087-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Високий score не доводить правильність вимог чи безпеку.`}]}]},{id:`T087-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Мутаційне тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Типові мутанти змінюють знак порівняння, прибирають умову або змінюють повернення.`},{id:`B`,text:`Мутаційне тестування вносить невеликі контрольовані зміни до коду й перевіряє, чи виявляють їх тести.`},{id:`C`,text:`Статичний аналіз доводить коректність усіх бізнес-правил під час виконання.`},{id:`D`,text:`Мутації, що вижили, завжди доводять продакшн-баг.`}]},{id:`T087-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Мутаційне тестування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Високий score не доводить правильність вимог чи безпеку.`},{id:`B`,text:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`},{id:`C`,text:`BDD-сценарії корисні лише QA, а не бізнес-сторонам.`},{id:`D`,text:`Високий mutation score гарантує відповідність продукту бізнес-вимогам.`}]},{id:`T087-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента знайти три конкретні запахи й запропонувати серію малих diff зі збереженою поведінкою та регресійними тестами.`},{id:`B`,text:`Попросіть агента скласти план тестів checkout, зіставити вимоги з найдешевшим ефективним рівнем і оцінити час прогону.`},{id:`C`,text:`Попросіть агента оцінити п’ять боргів за ризиком, частотою й ціною змін та запропонувати поетапне погашення з тестами й точками відкату.`},{id:`D`,text:`Попросіть агента запустити mutation testing правил цін, розібрати мутанти на межах і додати цільові тести замість формального збільшення coverage.`}]},{id:`T087-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Що показує мутант, який вижив, чого не видно з покриття рядків?`}]}]},{id:`T087-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Мутаційне тестування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T087-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Мутаційне тестування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T087-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T087-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Мутаційне тестування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Якщо заміна умови з менше на менше-або-дорівнює для знижки не ламає тести, межовий випадок недостатньо перевірений.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:87,questions:n};export{o as default,n as questions,i as slug,s as topicId};